//! Income analysis — what arrives, how regularly, and how much it MOVES.
//!
//! The variance is the part that matters, and it is the part a mean destroys. Two people earning
//! $4,000 a month on average are in completely different situations if one is salaried and the other
//! invoices lumpily — the second has months that do not cover rent, and an average says nothing about
//! them. Every downstream question (runway, what payment is sustainable, whether a balance transfer
//! is safe) turns on the low months, not the typical one.
//!
//! So this reports a MEDIAN and a SPREAD per source, and classifies stability rather than collapsing
//! everything to one number that reads as more certain than it is.
use crate::money::{money, Currency, Minor, Money};
use crate::txn::{days_between, merchant_key_default, month_of, Txn};

pub(crate) use median::median;
pub(crate) use round2::round2;
pub use classify_cadence::classify_cadence;
pub(crate) use consistency_of::consistency_of;
pub use stability_of::stability_of;
pub use expected_monthly::expected_monthly;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IncomeCadence {
    Weekly,
    Biweekly,
    /// Twice a month — the 1st and the 15th. NOT biweekly; see [`classify_cadence`].
    Semimonthly,
    Monthly,
    Irregular,
}

impl IncomeCadence {
    /// How many times this lands in an average month.
    ///
    /// Fractional on purpose: a weekly wage is 52 payments over 12 months, not 4. Rounding it to 4
    /// understates a year by four whole payments.
    pub fn per_month(self) -> Option<f64> {
        match self {
            IncomeCadence::Weekly => Some(52.0 / 12.0),
            IncomeCadence::Biweekly => Some(26.0 / 12.0),
            IncomeCadence::Semimonthly => Some(2.0),
            IncomeCadence::Monthly => Some(1.0),
            IncomeCadence::Irregular => None,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            IncomeCadence::Weekly => "weekly",
            IncomeCadence::Biweekly => "biweekly",
            IncomeCadence::Semimonthly => "semimonthly",
            IncomeCadence::Monthly => "monthly",
            IncomeCadence::Irregular => "irregular",
        }
    }
}

/// How much a source can be relied on, which is a different question from how much it pays.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stability {
    Steady,
    Variable,
    Lumpy,
}

impl Stability {
    pub fn label(self) -> &'static str {
        match self {
            Stability::Steady => "steady",
            Stability::Variable => "variable",
            Stability::Lumpy => "lumpy",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeSource {
    pub key: String,
    /// The most recent description, so a person recognises it.
    pub label: String,
    pub account: String,
    pub cadence: IncomeCadence,
    /// MEDIAN receipt — not the mean. One large invoice must not move the figure everything else
    /// depends on.
    pub typical: Money,
    /// The smallest receipt observed. What a bad month actually looked like, which is the number a
    /// runway calculation should be using.
    pub low: Money,
    pub high: Money,
    pub occurrences: usize,
    pub first_seen: String,
    pub last_seen: String,
    /// 0-1, to two decimals. How close the receipts are to each other; 1 is identical every time.
    pub consistency: f64,
    pub stability: Stability,
    /// Typical amount scaled to a month at this cadence — comparable across sources.
    pub monthly_equivalent: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct IncomeAnalysis {
    pub sources: Vec<IncomeSource>,
    /// Median TOTAL across whole months observed. The honest "usual month".
    pub typical_month: Money,
    /// The worst whole month observed. What the plan has to survive.
    pub worst_month: Money,
    pub best_month: Money,
    /// Whole months the analysis is computed over. A figure from two months is not an income
    /// pattern, and stating the coverage is what stops it being read as one.
    pub months_observed: usize,
    /// Inbound money that matched no repeating source — one-offs, transfers, refunds. Reported
    /// rather than folded in: a tax refund is not income you can plan on receiving again.
    pub one_off: Vec<Txn>,
}

pub struct IncomeOptions {
    /// Fewest receipts before a source counts as a source rather than a one-off.
    pub min_occurrences: usize,
}

impl Default for IncomeOptions {
    fn default() -> Self {
        IncomeOptions { min_occurrences: 3 }
    }
}

pub fn analyse_income(txns: &[Txn], currency: Currency, opts: &IncomeOptions) -> IncomeAnalysis {
    let inbound: Vec<&Txn> = txns.iter().filter(|t| t.amount.minor > 0).collect();

    // Insertion-ordered for the same reason as `recurring`: the output sort is stable, so ties fall
    // back to first-seen order and a hash map would make that vary between runs.
    let mut groups: Vec<((String, String), Vec<&Txn>)> = Vec::new();
    for t in &inbound {
        let key = merchant_key_default(&t.description);
        if key.is_empty() {
            continue;
        }
        // A `(account, key)` PAIR. The TypeScript joins these with a NUL byte and says why: a
        // merchant key is several words and an account name commonly holds one too ("Chase
        // Freedom"), so a space separator makes the join ambiguous and splitting it back hands the
        // caller a key with account text inside it. A tuple has nothing to split.
        let id = (t.account.clone(), key);
        match groups.iter_mut().find(|(gid, _)| *gid == id) {
            Some((_, bucket)) => bucket.push(t),
            None => groups.push((id, vec![t])),
        }
    }

    let mut sources: Vec<IncomeSource> = Vec::new();
    // Claimed by IDENTITY, which in Rust is the row's position rather than an object reference.
    let mut claimed: Vec<bool> = vec![false; inbound.len()];
    for (id, rows) in groups {
        if rows.len() < opts.min_occurrences {
            continue;
        }
        let mut sorted = rows;
        sorted.sort_by(|a, b| a.date.cmp(&b.date));
        let gaps: Vec<i64> = sorted.windows(2).map(|w| days_between(&w[0].date, &w[1].date)).collect();
        let cadence = classify_cadence(&gaps);
        if cadence == IncomeCadence::Irregular {
            continue;
        }

        let amounts: Vec<i64> = sorted.iter().map(|t| t.amount.minor).collect();
        let consistency = round2(consistency_of(&amounts));
        let typical = money(median(&amounts), currency);
        for t in &sorted {
            if let Some(i) = inbound.iter().position(|r| std::ptr::eq(*r, *t)) {
                claimed[i] = true;
            }
        }

        let per_month = cadence.per_month().expect("a classified cadence is never irregular");
        let last = sorted[sorted.len() - 1];
        sources.push(IncomeSource {
            key: id.1,
            label: last.description.clone(),
            // The FIRST row's account, while the label is the LAST row's description. Both come
            // from the same group, so they cannot disagree — the asymmetry is the TypeScript's and
            // is preserved rather than tidied, since tidying it would be an unmeasured change.
            account: sorted[0].account.clone(),
            cadence,
            typical,
            low: money(*amounts.iter().min().expect("a group has rows"), currency),
            high: money(*amounts.iter().max().expect("a group has rows"), currency),
            occurrences: sorted.len(),
            first_seen: sorted[0].date.clone(),
            last_seen: last.date.clone(),
            consistency,
            stability: stability_of(consistency),
            // Every receipt is inbound and so positive, which makes `f64::round` (half away from
            // zero) and `Math.round` (half toward +infinity) agree here.
            monthly_equivalent: money((typical.minor as f64 * per_month).round() as Minor, currency),
        });
    }

    // WHOLE months only. A partial month at either end reads as a catastrophic drop and would drag
    // the worst-month figure — the one a plan is built on — to something that never happened.
    let mut by_month: Vec<(String, i64)> = Vec::new();
    for t in &inbound {
        let m = month_of(&t.date).to_string();
        match by_month.iter_mut().find(|(k, _)| *k == m) {
            Some((_, v)) => *v += t.amount.minor,
            None => by_month.push((m, t.amount.minor)),
        }
    }
    by_month.sort_by(|a, b| a.0.cmp(&b.0));
    // With two months or fewer there is nothing to trim TO, so both partials are kept and
    // `months_observed` says how thin the basis is. Trimming here would leave zero months and
    // report every figure as 0, which reads as "no income" rather than "not enough data".
    let whole: &[(String, i64)] = if by_month.len() > 2 { &by_month[1..by_month.len() - 1] } else { &by_month };
    let totals: Vec<i64> = whole.iter().map(|(_, v)| *v).collect();

    sources.sort_by_key(|s| std::cmp::Reverse(s.monthly_equivalent.minor));
    IncomeAnalysis {
        sources,
        typical_month: money(if totals.is_empty() { 0 } else { median(&totals) }, currency),
        worst_month: money(totals.iter().min().copied().unwrap_or(0), currency),
        best_month: money(totals.iter().max().copied().unwrap_or(0), currency),
        months_observed: totals.len(),
        one_off: inbound.iter().enumerate().filter(|(i, _)| !claimed[*i]).map(|(_, t)| (*t).clone()).collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;

    // SYNTHETIC FIXTURES ONLY.
    fn t(date: &str, description: &str, minor: Minor) -> Txn {
        Txn { account: "a".to_string(), date: date.to_string(), description: description.to_string(), amount: usd(minor) }
    }

    fn analyse(rows: &[Txn]) -> IncomeAnalysis {
        analyse_income(rows, Currency::USD, &IncomeOptions::default())
    }

    /// Every expectation below was taken by TRANSPILING AND RUNNING `finance-income.ts`.
    #[test]
    fn a_biweekly_salary_is_twenty_six_payments_a_year_not_twenty_four() {
        let rows: Vec<Txn> = ["2026-01-02", "2026-01-16", "2026-01-30", "2026-02-13", "2026-02-27", "2026-03-13", "2026-03-27", "2026-04-10"]
            .iter()
            .map(|d| t(d, "ACME PAYROLL", 200_000))
            .collect();
        let a = analyse(&rows);
        assert_eq!(a.sources.len(), 1);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Biweekly);
        assert_eq!(s.typical.minor, 200_000);
        assert_eq!(s.consistency, 1.0);
        assert_eq!(s.stability, Stability::Steady);
        // 200000 * 26/12 = 433333.33 → 433333. At 4 payments a month it would read 800000, which is
        // the error this cadence exists to avoid.
        assert_eq!(s.monthly_equivalent.minor, 433_333);
        assert_eq!(a.months_observed, 2, "Jan and Apr are partial and are trimmed");
        assert_eq!(a.typical_month.minor, 400_000);
    }

    #[test]
    fn the_first_and_the_fifteenth_is_semimonthly_and_the_alternating_gap_is_what_says_so() {
        let rows: Vec<Txn> = ["2026-01-01", "2026-01-15", "2026-02-01", "2026-02-15", "2026-03-01", "2026-03-15", "2026-04-01"]
            .iter()
            .map(|d| t(d, "STATE PAYROLL", 150_000))
            .collect();
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Semimonthly, "the gaps alternate, so this is 24 a year");
        assert_eq!(s.monthly_equivalent.minor, 300_000);
        // A constant fortnight is the other answer, from the same median.
        assert_eq!(classify_cadence(&[14, 14, 14]), IncomeCadence::Biweekly);
        assert_eq!(classify_cadence(&[14, 17, 14, 17]), IncomeCadence::Semimonthly);
        // Two payments a month is 24 a year; a fortnight is 26. That gap is the whole point.
        assert_eq!(IncomeCadence::Semimonthly.per_month(), Some(2.0));
        assert!(IncomeCadence::Biweekly.per_month().unwrap() > 2.0);
    }

    #[test]
    fn a_lumpy_freelancer_reports_the_low_month_not_the_average() {
        let rows = vec![
            t("2026-01-05", "CLIENT INVOICE", 300_000),
            t("2026-02-04", "CLIENT INVOICE", 50_000),
            t("2026-03-06", "CLIENT INVOICE", 420_000),
            t("2026-04-05", "CLIENT INVOICE", 120_000),
        ];
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Monthly);
        assert_eq!(s.typical.minor, 210_000, "the median of the four receipts");
        assert_eq!(s.low.minor, 50_000, "the number a runway has to survive");
        assert_eq!(s.high.minor, 420_000);
        assert_eq!(s.consistency, 0.35);
        assert_eq!(s.stability, Stability::Lumpy);
        // The MEAN of the four is 222500, which is 4.45x the worst month. Nothing here reports it.
        assert_eq!(a.worst_month.minor, 50_000);
        assert_eq!(a.typical_month.minor, 235_000);
        assert_eq!(a.best_month.minor, 420_000);
    }

    #[test]
    fn a_weekly_wage_is_fifty_two_payments_a_year() {
        let rows: Vec<Txn> = [("2026-01-02", 40_000), ("2026-01-09", 42_000), ("2026-01-16", 38_000), ("2026-01-23", 41_000), ("2026-01-30", 39_000), ("2026-02-06", 40_000), ("2026-02-13", 40_000), ("2026-02-20", 40_000)]
            .iter()
            .map(|(d, m)| t(d, "GIG PLATFORM", *m))
            .collect();
        let a = analyse(&rows);
        let s = &a.sources[0];
        assert_eq!(s.cadence, IncomeCadence::Weekly);
        assert_eq!(s.consistency, 0.98);
        assert_eq!(s.stability, Stability::Steady);
        // 40000 * 52/12 = 173333.33 → 173333, not 160000.
        assert_eq!(s.monthly_equivalent.minor, 173_333);
    }

    #[test]
    fn a_tax_refund_is_reported_as_a_one_off_rather_than_folded_into_income() {
        let mut rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        rows.push(t("2026-02-10", "IRS TREAS REFUND", 180_000));
        let a = analyse(&rows);
        assert_eq!(a.sources.len(), 1, "the refund is not a source");
        assert_eq!(a.one_off.len(), 1);
        assert_eq!(a.one_off[0].description, "IRS TREAS REFUND");
        // It DOES move the month totals, because the money genuinely arrived — what it must not do
        // is become something the plan expects again.
        assert_eq!(a.best_month.minor, 580_000);
        assert_eq!(a.worst_month.minor, 400_000);
        assert_eq!(expected_monthly(&a, Currency::USD).unwrap().minor, 400_000, "the expectation excludes it");
    }

    #[test]
    fn two_months_of_data_keeps_both_partials_rather_than_trimming_to_nothing() {
        let rows: Vec<Txn> = ["2026-01-31", "2026-02-28", "2026-03-31"].iter().map(|d| t(d, "ACME PAYROLL", 400_000)).collect();
        let a = analyse(&rows);
        // Three CALENDAR months, so one is left after trimming.
        assert_eq!(a.months_observed, 1);
        assert_eq!(a.typical_month.minor, 400_000);
    }

    #[test]
    fn too_few_receipts_is_not_a_source_and_the_rows_stay_visible_as_one_offs() {
        let rows = vec![t("2026-01-05", "CLIENT INVOICE", 300_000), t("2026-02-04", "CLIENT INVOICE", 300_000)];
        let a = analyse(&rows);
        assert!(a.sources.is_empty(), "two receipts is below the default of three");
        assert_eq!(a.one_off.len(), 2, "and they are NOT silently dropped");
        assert_eq!(expected_monthly(&a, Currency::USD).unwrap().minor, 0);
    }

    #[test]
    fn nothing_inbound_reports_absence_rather_than_a_confident_zero_pattern() {
        let a = analyse(&[t("2026-01-05", "RENT LANDLORD LLC", -120_000)]);
        assert!(a.sources.is_empty());
        assert_eq!(a.months_observed, 0, "zero months observed is what says there is no basis");
        assert_eq!(a.typical_month.minor, 0);
        assert!(a.one_off.is_empty());
    }

    #[test]
    fn the_stability_thresholds_are_where_they_say_they_are() {
        assert_eq!(stability_of(0.9), Stability::Steady);
        assert_eq!(stability_of(0.89), Stability::Variable);
        assert_eq!(stability_of(0.6), Stability::Variable);
        assert_eq!(stability_of(0.59), Stability::Lumpy);
    }

    #[test]
    fn an_unrecognisable_rhythm_yields_no_source() {
        assert_eq!(classify_cadence(&[]), IncomeCadence::Irregular);
        assert_eq!(classify_cadence(&[60, 60]), IncomeCadence::Irregular);
        assert_eq!(IncomeCadence::Irregular.per_month(), None);
    }
}
